module.exports = function (data) {
  var payload = data.$trigger.payload;
  var field = data.$trigger.collection === 'services' ? 'impact_metric_sources' : 'sources';
  var pattern = new RegExp("^[Hh][Tt][Tt][Pp][Ss]://(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+[A-Za-z](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?::(?:[0-9]{1,4}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5]))?(?:[/?#][^\\s\\\\\\u0000-\\u001F\\u007F]*)?(?![\\s\\S])");
  var rows = Array.isArray(payload) ? payload : [payload];
  rows.forEach(function (item) {
    if (!item || !Object.prototype.hasOwnProperty.call(item, field) || item[field] === null) return;
    var sources = item[field];
    if (!Array.isArray(sources) || sources.some(function (source) {
      return !source || typeof source.label !== 'string' || !source.label.trim() ||
        typeof source.url !== 'string' || !pattern.test(source.url);
    })) {
      throw JSON.stringify({ name: 'DirectusError', code: 'FAILED_VALIDATION', status: 400,
        message: 'Every proof source needs a name and a public HTTPS URL without credentials.',
        extensions: { field: field, type: 'regex' } });
    }
  });
  return payload;
};
